-- ============================================================
-- ÎNTREBĂRI GRILĂ — bibliografia oficială a concursului 2026
-- Rulează în Supabase -> SQL Editor.
-- ============================================================
--
-- 121 de întrebări, generate din bibliografia aprobată prin
-- OMEC nr. 4.622/2026 (Anexa nr. 2) și din actele care reglementează
-- concursul. Fiecare întrebare are sursa exactă (act, titlu, capitol,
-- articol) și o explicație a răspunsului corect.
--
-- Fișierul adaugă întâi trei coloane noi în tabelul `questions`:
--   explanation    - de ce e corect răspunsul (se afișează după ce răspunzi)
--   difficulty     - usor / mediu / avansat
--   question_type  - recall / clasificare / capcana
-- Fără ele, explicațiile nu ar avea unde să fie stocate.
--
-- Nu conține grile despre procedura de concurs și despre calendar: acelea
-- verifică date administrative (termene, comisii), nu materia de examen.
-- Cele 37 de întrebări de acest tip au fost eliminate din set.
--
-- ȘTERGE întrebările existente (cele 5 de test din seed.sql) și pune
-- în loc setul oficial. Progresul la teste se șterge odată cu ele,
-- prin ON DELETE CASCADE — e inevitabil, întrebările vechi dispar.
--
-- Fișierul e re-rulabil: îl poți executa de mai multe ori fără dublare.
-- ============================================================

ALTER TABLE questions ADD COLUMN IF NOT EXISTS explanation TEXT;
ALTER TABLE questions ADD COLUMN IF NOT EXISTS difficulty TEXT;
ALTER TABLE questions ADD COLUMN IF NOT EXISTS question_type TEXT;

DELETE FROM questions;

INSERT INTO questions
  (text, option_a, option_b, option_c, option_d, correct_answer,
   source, category, explanation, difficulty, question_type) VALUES
('Pe câte niveluri este organizat profilul profesional al managerului școlar și care sunt acestea?', 'Trei: axiologic, profesional și funcțional', 'Patru: axiologic, transversal, profesional și funcțional', 'Cinci: axiologic, transversal, profesional, funcțional și operațional', 'Două: competențe generale și competențe specifice', 'B', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II — Arhitectura profilului', 'Profilul managerului școlar', 'Capitolul II descrie patru niveluri complementare: axiologic (valori fundamentale), transversal (competențe transversale), profesional (competențe generale și specifice) și funcțional (descriptori comportamentali). Varianta c) adaugă un nivel inexistent, iar a) omite nivelul transversal, care cuprinde precondițiile cognitive și relaționale.', 'mediu', 'recall'),
('Cărui nivel al profilului îi corespund „comportamentele observabile și măsurabile" asociate fiecărei competențe specifice?', 'Nivelul axiologic', 'Nivelul transversal', 'Nivelul profesional', 'Nivelul funcțional', 'D', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II lit. D', 'Profilul managerului școlar', 'Nivelul funcțional este definit ca fiind cel al descriptorilor comportamentali — „comportamente observabile și măsurabile, asociate fiecărei competențe specifice". Nivelul profesional conține competențele în sine, nu manifestările lor observabile.', 'mediu', 'clasificare'),
('Câte domenii de competență cuprinde nivelul profesional al profilului managerului școlar?', 'Trei', 'Patru', 'Cinci', 'Șapte', 'C', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II lit. C', 'Profilul managerului școlar', 'Profilul este structurat pe cinci domenii de competență: 1) leadership educațional, guvernanță instituțională și orientare strategică; 2) management operațional administrativ-financiar și conformitate; 3) managementul calității și evaluare internă; 4) managementul curriculumului, al proceselor de învățare și evaluare, dezvoltarea profesională a cadrelor didactice; 5) comunicare, relaționare, parteneriate și colaborare în comunitate. Cifra șapte corespunde competențelor TRANSVERSALE, nu domeniilor.', 'mediu', 'recall'),
('Cărui domeniu de competență îi aparține „managementul resurselor umane"?', 'Domeniul 1 — Leadership educațional, guvernanță instituțională și orientare strategică', 'Domeniul 2 — Management operațional administrativ-financiar și conformitate', 'Domeniul 4 — Managementul curriculumului, al proceselor de învățare și evaluare, dezvoltarea profesională a cadrelor didactice', 'Domeniul 5 — Comunicare, relaționare, parteneriate și colaborare în comunitate', 'C', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II lit. C, domeniul 4', 'Profilul managerului școlar', 'Competența specifică 4.1 „Managementul resurselor umane" este plasată în domeniul 4, alături de managementul implementării curriculumului, cercetare și inovație pedagogică, respectiv asigurarea succesului școlar. Plasarea poate surprinde — intuitiv, resursele umane par a ține de managementul operațional (domeniul 2) — dar profilul le leagă de dezvoltarea profesională a cadrelor didactice.', 'avansat', 'clasificare'),
('Care este natura juridică a Profilului profesional al managerului școlar?', 'Este fișa de post a directorului de unitate de învățământ', 'Nu se constituie într-o fișă de post, ci descrie așteptările față de managerul școlar în termeni de competențe', 'Este un ghid orientativ, fără caracter normativ', 'Este un regulament de organizare internă a unității', 'B', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul I — Context', 'Profilul managerului școlar', 'Capitolul I precizează expres: „Profilul propus nu se constituie într-o fișă de post, ci descrie așteptările exprimate față de managerul școlar în termeni de competențe și, în aceeași măsură, reia atribuțiile directorului". Varianta c) este greșită în sens contrar: profilul este aprobat prin ordin de ministru publicat în Monitorul Oficial, deci are caracter normativ, chiar dacă nu este fișă de post.', 'avansat', 'capcana'),
('Conform profilului, în ce raport se află sintagmele „manager școlar" și „director de unitate de învățământ preuniversitar"?', 'Sunt asimilate', 'Managerul școlar este superior ierarhic directorului', 'Managerul școlar desemnează exclusiv directorul adjunct', 'Sunt funcții distincte, cu atribuții diferite', 'A', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul I — Context', 'Profilul managerului școlar', 'Raportat la prevederile Legii nr. 198/2023, profilul precizează că sintagmele „manager școlar" și „director de unitate de învățământ preuniversitar" sunt asimilate. Documentul îl definește pe director drept „liderul pedagogic, strategic și organizațional al instituției".', 'usor', 'recall'),
('Care dintre următoarele NU figurează printre valorile fundamentale ale profilului managerului școlar?', 'Interesul superior al elevului', 'Etică și integritate profesională', 'Competitivitatea între unitățile de învățământ', 'Parteneriat cu familia și comunitatea', 'C', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II lit. A — valori fundamentale', 'Profilul managerului școlar', 'Profilul enumeră șase valori: interesul superior al elevului; echitate, incluziune și justiție socială; leadership pedagogic și cultură a învățării; etică și integritate profesională; inițiativă și antreprenoriat; parteneriat cu familia și comunitatea. Competitivitatea între școli nu apare — orientarea documentului este spre echitate și colaborare, nu spre concurență interinstituțională.', 'mediu', 'clasificare'),
('Ce prevede profilul în privința competențelor lingvistice ale managerului școlar?', 'Competențe de comunicare profesională exclusiv în limba română', 'Competențe lingvistice și de comunicare profesională în limba română și într-o limbă de circulație internațională', 'Cunoașterea obligatorie a două limbi de circulație internațională', 'Cunoașterea unei limbi a minorităților naționale', 'B', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II lit. B — competențe transversale', 'Profilul managerului școlar', 'Printre cele șapte competențe transversale figurează „competențe lingvistice și de comunicare profesională — în limba română și într-o limbă de circulație internațională, pentru redactare, argumentare și reprezentare instituțională". Cunoașterea unei limbi a minorităților este o cerință separată, prevăzută de art. 195 alin. (1) din Legea nr. 198/2023, aplicabilă doar unităților cu predare în limbile minorităților.', 'avansat', 'recall'),
('Cum este denumită în profil capacitatea de adaptare și învățare continuă în contexte de schimbare și incertitudine?', 'Leadership transformațional', 'Leadership adaptativ', 'Leadership distribuit', 'Leadership tranzacțional', 'B', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II lit. B — competențe transversale', 'Profilul managerului școlar', 'Profilul denumește această competență transversală „capacitate de adaptare și învățare continuă (leadership adaptativ) — în contexte de schimbare, incertitudine și complexitate sistemică". Celelalte denumiri sunt modele de leadership din literatura de specialitate, nu termenii folosiți de acest act normativ.', 'mediu', 'clasificare'),
('În ce Monitor Oficial a fost publicat Profilul profesional al managerului școlar?', 'Monitorul Oficial nr. 469 din 4 iunie 2026', 'Monitorul Oficial nr. 552 bis din 6 iulie 2026', 'Monitorul Oficial nr. 664 din 11 august 2026', 'Monitorul Oficial nr. 795 din 12 august 2024', 'A', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Ordin nr. 3.934 din 18 mai 2026', 'Profilul managerului școlar', 'OMEC nr. 3.934 din 18 mai 2026 a fost publicat în Monitorul Oficial nr. 469 din 4 iunie 2026. Celelalte variante corespund altor acte din aceeași bibliografie: MO 552 bis/6 iulie 2026 — Metodologia (OMEC 4.155/2026); MO 664/11 august 2026 — Calendarul și bibliografia (OMEC 4.622/2026); MO 795/12 august 2024 — Regulamentul-cadru (OMEC 5.726/2024).', 'avansat', 'recall'),
('Conform art. 1 alin. (1), în ce limbi se desfășoară învățământul preuniversitar din România?', 'Exclusiv în limba română', 'În limba română și în limbile minorităților naționale', 'În limba română, în limbile minorităților naționale, în limba semnelor române și în limbi de circulație internațională', 'În limba română și în limbi de circulație internațională', 'C', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. I, art. 1 alin. (1)', 'Legislație', 'Art. 1 alin. (1) enumeră patru categorii: limba română, limbile minorităților naționale, limba semnelor române și limbile de circulație internațională. Includerea explicită a limbii semnelor române este elementul cel mai des omis.', 'usor', 'recall'),
('Ce statut are învățământul preuniversitar potrivit art. 1 alin. (1)?', 'Constituie prioritate națională și este domeniu de interes public', 'Este serviciu public de interes local', 'Este activitate economică de interes general', 'Este domeniu de interes strategic în subordinea autorităților locale', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. I, art. 1 alin. (1)', 'Legislație', 'Art. 1 alin. (1) prevede că „învățământul preuniversitar constituie prioritate națională, este domeniu de interes public". Formularea este esențială pentru că fundamentează întregul regim juridic al finanțării și organizării sistemului.', 'usor', 'recall'),
('În ce constă idealul educațional al școlii românești, potrivit art. 1 alin. (3)?', 'În pregătirea elevilor pentru examenele naționale', 'În dezvoltarea liberă, integrală și armonioasă a individualității umane, în formarea personalității autonome și în asumarea unui sistem de valori', 'În formarea forței de muncă necesare economiei naționale', 'În transmiterea valorilor culturale ale poporului român', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. I, art. 1 alin. (3)', 'Legislație', 'Art. 1 alin. (3) definește idealul educațional ca „dezvoltarea liberă, integrală și armonioasă a individualității umane, în formarea personalității autonome și în asumarea unui sistem de valori care sunt necesare pentru împlinirea și dezvoltarea personală, pentru dezvoltarea spiritului antreprenorial, pentru participarea cetățenească activă în societate, pentru incluziune socială și pentru angajare pe piața muncii". Angajarea pe piața muncii este doar una dintre finalități, nu idealul în sine.', 'mediu', 'recall'),
('Cărui principiu îi corespunde „redistribuirea autorității decizionale de la nivelurile centrale către cele locale, pentru a răspunde adecvat nevoilor beneficiarilor"?', 'Principiul eficienței', 'Principiul relevanței', 'Principiul descentralizării decizionale', 'Principiul echității și egalității de șanse', 'C', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. I, art. 3', 'Legislație', 'Art. 3 lit. e) definește principiul descentralizării decizionale exact în acești termeni. Principiul eficienței (lit. d) vizează obținerea rezultatelor preconizate prin gestionarea resurselor existente, iar principiul relevanței (lit. c) o ofertă educațională corelată cu nevoile elevilor și cerințele pieței muncii.', 'mediu', 'clasificare'),
('Ce include expres principiul nediscriminării, potrivit art. 3 lit. a)?', 'Interzicerea segregării școlare', 'Obligativitatea învățământului gratuit până la 18 ani', 'Dreptul la educație în limba maternă', 'Asigurarea transportului școlar gratuit', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. I, art. 3 lit. a)', 'Legislație', 'Art. 3 lit. a) prevede că accesul și participarea la educația de calitate se realizează fără discriminare, „inclusiv prin interzicerea segregării școlare". Interdicția segregării este așadar o componentă a principiului nediscriminării, nu un principiu separat. Celelalte variante sunt drepturi reale, dar reglementate în alte texte ale legii.', 'avansat', 'capcana'),
('Pe ce bază se realizează recrutarea, încadrarea, formarea și evaluarea persoanelor care realizează managementul unităților de învățământ?', 'Pe baza regulamentului intern al fiecărei unități', 'Pe baza standardelor profesionale care formează profilul profesional al managerului școlar, aprobate prin ordin al ministrului educației', 'Pe baza criteriilor stabilite anual de consiliul de administrație al inspectoratului', 'Pe baza standardelor ARACIIP', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 194 alin. (1)', 'Legislație', 'Art. 194 alin. (1) stabilește această bază legală, iar profilul respectiv a fost aprobat prin OMEC nr. 3.934/2026. Această legătură explică de ce Profilul figurează în bibliografia concursului: el este instrumentul prin care legea operaționalizează recrutarea și evaluarea directorilor.', 'mediu', 'recall'),
('Când are directorul obligația de a urma programul de formare profesională în management școlar?', 'Înainte de a se înscrie la concurs', 'În primul an al fiecărui mandat de management', 'O singură dată, în primul an al primului mandat', 'În ultimul an al mandatului, ca o condiție de reînnoire', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 194 alin. (4)', 'Legislație', 'Art. 194 alin. (4) prevede obligația de a urma programul „în primul an al FIECĂRUI mandat de management", nu doar la primul mandat. Programul reprezintă totodată criteriu de evaluare a activității manageriale. Capcana este varianta c): consilierea de către un mentor, reglementată la alin. (6), este cea care se aplică doar la PRIMUL mandat.', 'avansat', 'capcana'),
('Cine beneficiază de consiliere din partea unui mentor pentru management educațional?', 'Toți directorii, pe întreaga durată a mandatului', 'Directorul și directorul adjunct care exercită primul mandat de management educațional', 'Numai directorii unităților cu rezultate slabe la evaluările naționale', 'Numai directorii adjuncți', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 194 alin. (6)', 'Legislație', 'Art. 194 alin. (6): directorul și directorul adjunct care exercită PRIMUL mandat de management educațional sunt consiliați în activitate de un mentor pentru management educațional. Mentorii formează Corpul Managerilor Educaționali, înființat prin alin. (7).', 'avansat', 'clasificare'),
('Ce este Corpul Managerilor Educaționali?', 'Un sindicat al directorilor de unități de învățământ', 'Un organism de specialitate aflat în coordonarea Ministerului Educației, format din mentorii pentru management educațional', 'O structură din cadrul fiecărui inspectorat școlar județean', 'Comisia națională de monitorizare a concursului de directori', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 194 alin. (7)', 'Legislație', 'Art. 194 alin. (7) înființează Corpul Managerilor Educaționali ca organism de specialitate în coordonarea Ministerului Educației, format din mentorii pentru management educațional. Scopul: dezvoltarea politicilor publice din educație, mentoratul directorilor aflați la început de carieră și monitorizarea respectării principiilor etice în managementul școlar.', 'mediu', 'recall'),
('Funcțiile de conducere, de îndrumare și control din învățământul preuniversitar sunt funcții publice în sensul OUG nr. 57/2019?', 'Da, toate sunt funcții publice', 'Nu sunt funcții publice prevăzute de OUG nr. 57/2019', 'Doar funcțiile de la nivelul ministerului sunt funcții publice', 'Doar funcțiile de inspector școlar sunt funcții publice', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 194 alin. (9)', 'Legislație', 'Art. 194 alin. (9) prevede expres că funcțiile de conducere, îndrumare și control și funcțiile de la nivelul DJIP/DMBIP, CNFDCD, CCD, ARACIIP, al birourilor județene ale acesteia și al CJRAE/CMBRAE NU sunt funcții publice prevăzute de OUG nr. 57/2019. Consecința practică: raporturile acestor persoane sunt de muncă, nu de serviciu, cu regim juridic diferit.', 'avansat', 'capcana'),
('Cine exercită conducerea executivă a unității de învățământ?', 'Consiliul de administrație', 'Directorul', 'Consiliul profesoral', 'Inspectorul școlar general', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 195 alin. (1)', 'Legislație', 'Art. 195 alin. (1) este categoric: „Directorul exercită conducerea executivă a unității de învățământ". Art. 195 alin. (2) lit. a) adaugă faptul că directorul este reprezentantul legal al unității. Consiliul de administrație are rol de decizie în domeniile de competență proprii, dar nu exercită conducerea executivă.', 'usor', 'recall'),
('Într-o unitate de învățământ cu SECȚII de predare în limba unei minorități naționale, cine are obligația cunoașterii limbii respective?', 'Toți membrii echipei de conducere', 'Unul dintre directori', 'Directorul, în mod obligatoriu', 'Niciunul; obligația revine doar cadrelor didactice', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 195 alin. (1)', 'Legislație', 'Art. 195 alin. (1) face o distincție fină: la unitățile cu predare INTEGRALĂ în limbile minorităților, DIRECTORUL are obligația cunoașterii limbii; la unitățile cu SECȚII de predare în limbile minorităților sau cu studiul limbii minorității, obligația revine UNUIA DINTRE directori. Confuzia între cele două ipoteze este exact capcana. În ambele cazuri, numirea se face cu consultarea organizației care reprezintă minoritatea în Parlament sau a Grupului parlamentar al minorităților naționale.', 'avansat', 'capcana'),
('Care sunt funcțiile de conducere de la nivelul unității de învățământ preuniversitar?', 'Director general și director general adjunct', 'Director și director adjunct', 'Director, director adjunct și inspector școlar', 'Director și administrator de patrimoniu', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 194 alin. (2) lit. d)', 'Legislație', 'Art. 194 alin. (2) lit. d) prevede pentru nivelul unității de învățământ/unității de educație extrașcolară funcțiile de director și director adjunct. Director general și director general adjunct sunt funcțiile de la nivelul DJIP/DMBIP (lit. a), iar inspectorul școlar este funcție de îndrumare și control (lit. c) — deci la alt nivel. Administratorul de patrimoniu este personal didactic auxiliar (art. 192).', 'mediu', 'clasificare'),
('Care dintre următoarele funcții face parte din personalul didactic AUXILIAR?', 'Director adjunct', 'Inspector școlar', 'Mediator școlar', 'Profesor pentru învățământ primar', 'C', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. X, art. 192 alin. (1)', 'Legislație', 'Art. 192 alin. (1) enumeră personalul didactic auxiliar: bibliotecar, documentarist, redactor, informatician, analist programator, laborant, tehnician, pedagog școlar, instructor de educație extrașcolară, asistent social, corepetitor, mediator școlar, secretar, administrator financiar (contabil), instructor-animator, administrator de patrimoniu, referent. Directorul adjunct și inspectorul școlar sunt funcții didactice de conducere, respectiv de îndrumare și control (art. 194).', 'mediu', 'clasificare'),
('Care dintre următoarele NU figurează în lista personalului didactic auxiliar de la art. 192?', 'Administrator de patrimoniu', 'Corepetitor', 'Consilier școlar', 'Instructor-animator', 'C', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. X, art. 192 alin. (1)', 'Legislație', 'Lista de la art. 192 alin. (1) include administratorul de patrimoniu, corepetitorul și instructorul-animator, dar nu și consilierul școlar — acesta are statut de personal didactic și activează în cadrul CJRAE/CMBRAE și al cabinetelor de asistență psihopedagogică, reglementat separat.', 'avansat', 'clasificare'),
('Care este prima sancțiune disciplinară, în ordinea gravității, care se poate aplica personalului didactic de predare?', 'Avertismentul scris', 'Reducerea salariului de bază cu până la 15%', 'Suspendarea dreptului de a se înscrie la concursuri', 'Desfacerea disciplinară a contractului de muncă', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XIV, art. 210 alin. (1)', 'Legislație', 'Art. 210 alin. (1) enumeră sancțiunile în raport cu gravitatea abaterilor, începând cu lit. a) avertismentul scris, urmat de lit. b) reducerea salariului de bază, cumulat, când este cazul, cu indemnizația de conducere, de îndrumare și control, cu până la 15%, pe o perioadă de 1-6 luni, apoi lit. c) suspendarea etc.', 'mediu', 'recall'),
('Care este cuantumul maxim și durata reducerii salariului de bază, ca sancțiune disciplinară?', 'Până la 10%, pe o perioadă de 1-3 luni', 'Până la 15%, pe o perioadă de 1-6 luni', 'Până la 25%, pe o perioadă de 1-6 luni', 'Până la 15%, pe o perioadă de 3-12 luni', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XIV, art. 210 alin. (1) lit. b)', 'Legislație', 'Art. 210 alin. (1) lit. b) prevede reducerea salariului de bază, cumulat — când este cazul — cu indemnizația de conducere, de îndrumare și control, cu până la 15%, pe o perioadă de 1-6 luni. Atât procentul, cât și intervalul sunt ușor de confundat cu cele din Codul muncii pentru alte categorii de salariați.', 'avansat', 'capcana'),
('Care este situația actuală a art. 207 din capitolul XIII al Titlului III?', 'Este în vigoare în forma inițială din 2023', 'A fost modificat prin OUG nr. 95/2024', 'A fost abrogat prin Legea nr. 141/2025', 'A fost suspendat până în anul școlar 2026-2027', 'C', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XIII, art. 207', 'Legislație', 'Art. 207, Capitolul XIII, Titlul III a fost ABROGAT prin pct. 10 al art. LIII din Legea nr. 141 din 25 iulie 2025, publicată în Monitorul Oficial nr. 699 din 25 iulie 2025. Este o capcană importantă: bibliografia trimite la capitolul XIII, dar din el a rămas aplicabil practic doar art. 208 (norma didactică). Varianta d) descrie o altă situație reală din lege — prorogarea art. 190 alin. (6) și art. 229 alin. (14) până la începutul anului școlar 2026-2027 — care nu privește art. 207.', 'avansat', 'capcana'),
('Ce număr minim de credite transferabile trebuie să aibă modulul care atestă competențe de predare a unei noi discipline, pentru a fi luat în calcul la norma didactică?', '30 de credite', '60 de credite', '90 de credite', '120 de credite', 'C', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XIII, art. 208 alin. (1)', 'Legislație', 'Art. 208 alin. (1) prevede că norma didactică cuprinde ore la disciplinele corespunzătoare specializării sau specializărilor înscrise pe diploma de licență ori pe certificatul de absolvire a unui modul de minimum 90 de credite transferabile care atestă obținerea de competențe de predare a unei noi discipline.', 'avansat', 'recall'),
('Din ce izvoare decurg drepturile și obligațiile personalului din învățământul preuniversitar, potrivit art. 219 alin. (1)?', 'Exclusiv din contractul individual de muncă', 'Din legislația în vigoare, din lege, din regulamente specifice, precum și din contractul individual și cel colectiv de muncă aplicabil', 'Exclusiv din Legea nr. 198/2023', 'Din regulamentul intern al unității și din fișa postului', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XVI, art. 219 alin. (1)', 'Legislație', 'Art. 219 alin. (1) enumeră toate aceste izvoare cumulativ. Enumerarea contează practic: directorul nu poate invoca doar regulamentul intern pentru a restrânge drepturi prevăzute în contractul colectiv de muncă aplicabil sau în lege.', 'mediu', 'recall'),
('De ce beneficiază personalul din învățământul preuniversitar potrivit art. 219 alin. (2)?', 'De asistență medicală gratuită pentru examinările medicale periodice prevăzute de legislația în vigoare', 'De asigurare privată de sănătate suportată integral de angajator', 'De concediu medical nelimitat', 'De decontarea integrală a tratamentelor stomatologice', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XVI, art. 219 alin. (2)', 'Legislație', 'Art. 219 alin. (2) prevede că personalul beneficiază de asistență medicală gratuită pentru examinările medicale periodice prevăzute de legislația în vigoare. Este un drept concret și delimitat, nu o acoperire medicală generală.', 'mediu', 'recall'),
('Ce prevede legea pentru personalul didactic titular care a dobândit titlul de profesor emerit?', 'Are prioritate la ocuparea unui post sau a unei catedre', 'Beneficiază de pensionare anticipată fără penalizare', 'Este scutit de evaluarea anuală', 'Devine automat membru al consiliului de administrație', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. IX, art. 190', 'Legislație', 'Art. 190 prevede că personalul didactic titular care a dobândit titlul de profesor emerit are prioritate la ocuparea unui post/unei catedre. De reținut că alin. (6) al aceluiași articol, împreună cu art. 229 alin. (14), a fost prorogat până la începutul anului școlar 2026-2027 prin art. XLIII alin. (1) lit. g) din Legea nr. 141/2025.', 'avansat', 'recall'),
('Care sunt cele trei dimensiuni pe care Bush le folosește ca bază pentru o definiție funcțională a leadershipului?', 'Influență, valori și viziune', 'Autoritate, control și evaluare', 'Planificare, organizare și coordonare', 'Competență, carismă și rezultate', 'A', 'Bush, T., Leadership și management educațional, Editura Polirom — Capitolul 1 — Importanța leadershipului și a managementului educațional', 'Leadership educațional (Bush)', 'Bush structurează capitolul 1 în jurul a trei dimensiuni ale leadershipului — influența, valorile și viziunea — pe care le folosește pentru a construi o definiție funcțională. Varianta c) enumeră funcții clasice ale MANAGEMENTULUI, tocmai distincția pe care capitolul o problematizează.', 'mediu', 'recall'),
('Cum este caracterizat leadershipul ca proces de influență, în definiția reținută de Bush?', 'Un proces spontan, lipsit de intenționalitate', 'Un proces de influență socială cu o dimensiune intenționată, exercitat de un individ sau grup asupra altor indivizi sau grupuri, pentru a structura activitățile și relațiile', 'Un proces exercitat exclusiv de persoane aflate în poziții formale de autoritate', 'Un proces de transmitere a deciziilor ierarhice', 'B', 'Bush, T., Leadership și management educațional, Editura Polirom — Capitolul 1 — Leadershipul ca influență', 'Leadership educațional (Bush)', 'Bush reține ipoteza că leadershipul implică „un proces de influență socială incluzând o dimensiune intenționată exercitată de un singur individ [sau de un grup] asupra altor indivizi [sau grupuri] cu scopul de a structura activitățile și relațiile". Detaliile care contează: influența este INTENȚIONATĂ și poate proveni de la un grup, nu doar de la un individ, și nu presupune obligatoriu o poziție formală.', 'mediu', 'recall'),
('De ce consideră Bush că noțiunea de „influență" este insuficientă pentru a defini leadershipul?', 'Pentru că influența nu poate fi măsurată empiric', 'Pentru că influența este neutră — nu explică și nu recomandă scopurile sau acțiunile care ar trebui avute în vedere', 'Pentru că influența se exercită doar pe verticală, ierarhic', 'Pentru că influența aparține managementului, nu leadershipului', 'B', 'Bush, T., Leadership și management educațional, Editura Polirom — Capitolul 1 — Leadershipul și valorile', 'Leadership educațional (Bush)', 'Bush arată explicit că „noțiunea de «influență» este neutră prin faptul că nici nu explică, nici nu recomandă scopurile sau acțiunile ce ar trebui avute în vedere". Tocmai acest deficit justifică adăugarea dimensiunii valorilor: se așteaptă ca liderii să-și fundamenteze acțiunile pe valori personale și profesionale clare. Greenfield și Ribbins (1993) susțin că leadershipul începe cu „caracterul" liderilor.', 'avansat', 'capcana'),
('Citatul „Managementul nu are scopuri și valori supraordonate proprii. Aspirația spre eficiență poate fi misiunea managementului, dar aceasta se manifestă în realizarea obiectivelor definite de alții" aparține:', 'Lui Greenfield și Ribbins (1993)', 'Lui Newman și Clarke (1994)', 'Lui Gunter (1997)', 'Lui Hattie (2012)', 'B', 'Bush, T., Leadership și management educațional, Editura Polirom — Capitolul 1 — Importanța leadershipului și a managementului educațional', 'Leadership educațional (Bush)', 'Citatul este atribuit de Bush lui Newman și Clarke (1994: 29). Greenfield și Ribbins (1993) sunt citați în legătură cu ideea că leadershipul începe cu „caracterul" liderilor, iar Gunter (1997) apare într-o trimitere alăturată privind managementul educației. Argumentul lui Newman și Clarke este important pentru că susține distincția dintre management — orientat spre eficiență în realizarea unor scopuri stabilite de alții — și leadership, asociat cu valori și scopuri proprii.', 'avansat', 'clasificare'),
('De ce tratează Bush leadershipul instruirii în capitolul 1, și nu alături de celelalte modele de leadership?', 'Pentru că este cel mai important model de leadership educațional', 'Pentru că are în vedere direcția influenței, în detrimentul naturii și sursei acesteia, deci nu face obiectul volumului', 'Pentru că este singurul model validat empiric', 'Pentru că a fost abandonat de literatura de specialitate', 'B', 'Bush, T., Leadership și management educațional, Editura Polirom — Capitolul 1 — Leadershipul instruirii', 'Leadership educațional (Bush)', 'Bush explică: „leadershipul instruirii nu face obiectul acestui volum, deoarece are în vedere direcția influenței, în detrimentul naturii și sursei acesteia, astfel încât subiectul va fi abordat aici". Criteriul de selecție al volumului este așadar natura și sursa influenței, nu direcția ei. Celelalte modele urmează să fie prezentate în capitolul 2.', 'avansat', 'capcana'),
('Ce tendință internațională identifică Bush ca influențând rolul conducerii școlare?', 'Tendința spre management descentralizat', 'Tendința spre recentralizarea deciziei la nivel ministerial', 'Tendința spre desființarea funcțiilor de conducere', 'Tendința spremanagement privat al școlilor publice', 'A', 'Bush, T., Leadership și management educațional, Editura Polirom — Capitolul 1 — Importanța leadershipului și a managementului educațional', 'Leadership educațional (Bush)', 'Capitolul 1 discută tendința internațională spre management descentralizat, care sporește autonomia și, implicit, responsabilitatea conducerii școlare. Această tendință explică de ce leadershipul școlar a devenit un domeniu de studiu distinct.', 'mediu', 'recall'),
('Potrivit capitolului 1, cum a evoluat denumirea domeniului de studiu al conducerii școlare?', 'De la „leadership" la „administrație"', 'De la „administrație" spre „management" și apoi „leadership"', 'De la „management" la „supervizare"', 'Denumirea a rămas neschimbată de la începutul secolului XX', 'B', 'Bush, T., Leadership și management educațional, Editura Polirom — Capitolul 1 — Importanța leadershipului și a managementului educațional', 'Leadership educațional (Bush)', 'Capitolul descrie evoluția terminologică dinspre „administrație" spre „management" și ulterior spre „leadership", evoluție care reflectă o schimbare de accent: de la executarea procedurilor la conducerea orientată spre scopuri și valori. Bush avertizează însă asupra riscului dihotomiei simpliste între un „leadership" valorizat și un „management" devalorizat.', 'mediu', 'clasificare'),
('Ce susțin Greenfield și Ribbins (1993) despre punctul de plecare al leadershipului?', 'Că leadershipul începe cu structura organizațională', 'Că leadershipul începe cu „caracterul" liderilor', 'Că leadershipul începe cu rezultatele măsurabile ale elevilor', 'Că leadershipul începe cu delegarea autorității', 'B', 'Bush, T., Leadership și management educațional, Editura Polirom — Capitolul 1 — Leadershipul și valorile', 'Leadership educațional (Bush)', 'Bush îi citează pe Greenfield și Ribbins (1993) pentru teza că leadershipul începe cu „caracterul" liderilor. Această poziție susține dimensiunea valorică a leadershipului: se așteaptă ca liderii să-și fundamenteze acțiunile pe valori personale și profesionale clare.', 'mediu', 'recall'),
('Care este prima concepție (structură mentală) enunțată de Hattie în capitolul 9?', 'Profesorii/liderii cred că sarcina lor fundamentală este să evalueze efectele predării lor asupra învățării și progreselor elevilor', 'Profesorii/liderii vor să vorbească mai mult despre învățare decât despre predare', 'Profesorii/liderii se angajează în dialog, nu în monolog', 'Profesorii/liderii îi informează pe toți cu privire la limbajul învățării', 'A', 'Hattie, J., Învățarea vizibilă, Editura Polirom — Capitolul 9 — Structurile mentale ale profesorilor, directorilor și sistemelor școlare', 'Învățarea vizibilă (Hattie)', 'Concepția 1 formulează ideea centrală a întregii lucrări: sarcina fundamentală a profesorilor și liderilor este evaluarea efectelor propriei predări asupra învățării și progreselor elevilor. Celelalte variante sunt tot concepții autentice din capitol — Concepția 3, 5 și respectiv 8 — ceea ce face întrebarea una de ordonare, nu doar de recunoaștere.', 'mediu', 'recall'),
('Câte concepții (structuri mentale) sunt prezentate în capitolul 9?', 'Cinci', 'Șase', 'Opt', 'Zece', 'C', 'Hattie, J., Învățarea vizibilă, Editura Polirom — Capitolul 9 — Structurile mentale', 'Învățarea vizibilă (Hattie)', 'Capitolul 9 prezintă opt concepții, de la Concepția 1 (evaluarea efectelor propriei predări) până la Concepția 8 (informarea tuturor cu privire la limbajul învățării).', 'mediu', 'recall'),
('Ce prag al mărimii efectului cere Hattie pentru progresul anual al elevilor?', 'd > 0,20', 'd > 0,40', 'd > 0,60', 'd > 1,00', 'B', 'Hattie, J., Învățarea vizibilă, Editura Polirom — Capitolul 9 — Structurile mentale', 'Învățarea vizibilă (Hattie)', 'Recomandarea din capitol este explicită: „Asigură-te că toți elevii se dezvoltă la un prag de cel puțin d = >0,40 în fiecare an în această școală la nivel de învățare semnificativă". Capcana o reprezintă varianta a): Hattie avertizează chiar că trebuie eliminate practicile care obțin d > 0, dar nu și d > 0,40 — adică un efect pozitiv, dar insuficient, nu este un criteriu de succes.', 'avansat', 'capcana'),
('Concepția 2 din capitolul 9 afirmă că succesul și eșecul în învățarea elevilor:', 'Depind în principal de mediul socioeconomic al familiei', 'Se traduc prin ceea ce profesorii și liderii, ca dascăli sau coordonatori, au făcut', 'Sunt determinate de capacitatea înnăscută a elevului', 'Reflectă calitatea manualelor și a resurselor didactice', 'B', 'Hattie, J., Învățarea vizibilă, Editura Polirom — Capitolul 9 — Concepția 2', 'Învățarea vizibilă (Hattie)', 'Concepția 2 plasează responsabilitatea la nivelul acțiunii profesorilor și liderilor. Capitolul critică explicit discursurile de tipul „Totul se trage de la sărăcie și de la mediul de acasă", pe care le tratează drept moduri de a externaliza responsabilitatea. Varianta a) este exact poziția pe care Hattie o contestă.', 'avansat', 'clasificare'),
('Cum trebuie privită evaluarea, potrivit Concepției 4?', 'Ca instrument de ierarhizare a elevilor', 'Ca feedback despre propriul impact al profesorului sau liderului', 'Ca obligație administrativă de raportare', 'Ca mijloc de selecție pentru treapta următoare de învățământ', 'B', 'Hattie, J., Învățarea vizibilă, Editura Polirom — Capitolul 9 — Concepția 4', 'Învățarea vizibilă (Hattie)', 'Concepția 4 reformulează radical rolul evaluării: profesorii și liderii „văd evaluarea ca un feedback despre propriul impact". Deplasarea este de la evaluarea elevului la evaluarea efectului predării — evaluarea devine informație despre profesor, nu doar despre elev. Celelalte variante descriu funcții tradiționale ale evaluării, pe care capitolul le consideră insuficiente.', 'avansat', 'capcana'),
('Concepția 7 se referă la dezvoltarea relațiilor pozitive. Unde anume?', 'Exclusiv în sălile de clasă', 'În sălile de clasă și în cancelarii', 'Exclusiv în relația cu părinții', 'În relația cu autoritățile locale', 'B', 'Hattie, J., Învățarea vizibilă, Editura Polirom — Capitolul 9 — Concepția 7 și Anexa A', 'Învățarea vizibilă (Hattie)', 'Concepția 7 afirmă că profesorii și liderii „cred că face parte din rolul lor să dezvolte relații pozitive în sălile de clasă ȘI în cancelarii". Extinderea la cancelarie este esențială: capitolul critică preocuparea exclusivă pentru climatul din sala de clasă, ignorând climatul dintre adulții școlii, care condiționează colaborarea profesională.', 'mediu', 'clasificare'),
('Potrivit art. 196 alin. (1), procedura de recrutare și selecție a directorilor cuprinde următoarele etape:', 'Evaluare de competențe, probă scrisă și interviu', 'Evaluarea dosarului, probă scrisă și inspecție la clasă', 'Probă scrisă, probă practică și interviu', 'Evaluare psihologică, probă scrisă și evaluarea planului managerial', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 196 alin. (1)', 'Legislație', 'Art. 196 alin. (1) enumeră: a) evaluare de competențe, realizată de comisia de concurs împreună cu specialiști în psihometrie; b) probă scrisă; c) interviu. Legea stabilește arhitectura în trei etape, iar Metodologia (art. 19) o preia identic. De reținut: la interviu se evaluează atât capacitățile și aptitudinile personale, cât și calitatea planului managerial și a planului de acțiune.', 'mediu', 'recall'),
('Cine realizează evaluarea de competențe, potrivit art. 196 alin. (1) lit. a)?', 'Exclusiv comisia de concurs', 'Comisia de concurs împreună cu specialiști în psihometrie', 'Exclusiv specialiști în psihometrie desemnați de minister', 'Consiliul de administrație al unității de învățământ', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 196 alin. (1) lit. a)', 'Legislație', 'Legea prevede că evaluarea se realizează de comisia de concurs ÎMPREUNĂ cu specialiști în psihometrie. Prezența psihometricienilor nu este opțională. Detaliul se leagă de art. 21 din Metodologie, unde elaborarea testelor standardizate implică tot specialiști în psihometrie, alături de experți în științele educației.', 'avansat', 'capcana'),
('Pentru ce perioadă sunt numite persoanele care au câștigat concursul pentru funcția de director?', '2 ani', '3 ani', '4 ani', '5 ani', 'C', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 196 alin. (4)', 'Legislație', 'Art. 196 alin. (4) stabilește durata mandatului la 4 ani. Aceeași durată apare și în art. 32 alin. (1) din Metodologie, atât pentru decizia de numire, cât și pentru contractul de management educațional. Durata de 5 ani corespunde vechimii minime cerute la înscriere, nu mandatului — o confuzie frecventă.', 'usor', 'recall'),
('Câte contracte de management încheie directorul unei unități de învățământ de stat și cu cine?', 'Unul singur, de management educațional, cu directorul general al DJIP/DMBIP', 'Două: unul de management educațional cu directorul general al DJIP/DMBIP și unul de management administrativ-financiar cu primarul', 'Unul singur, cu consiliul de administrație al unității', 'Două: unul cu primarul și unul cu consiliul local', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 196 alin. (4)-(5)', 'Legislație', 'Sunt DOUĂ contracte distincte. Art. 196 alin. (4): contractul de management educațional se încheie cu directorul general al DJIP/DMBIP. Art. 196 alin. (5): planul de management administrativ-financiar se supune avizării consiliului de administrație al unității și apoi aprobării primarului, iar contractul de management administrativ-financiar se încheie cu primarul. Dualitatea reflectă dubla subordonare a școlii: pedagogic față de structura de învățământ, administrativ-financiar față de autoritatea locală.', 'avansat', 'capcana'),
('Ce parcurs urmează planul de management administrativ-financiar înainte de încheierea contractului?', 'Este aprobat direct de primar', 'Este avizat de consiliul de administrație al unității, apoi aprobat de primar', 'Este avizat de consiliul profesoral, apoi aprobat de consiliul local', 'Este aprobat de directorul general al DJIP/DMBIP', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 196 alin. (5)', 'Legislație', 'Art. 196 alin. (5) descrie două trepte succesive: mai întâi AVIZAREA de către consiliul de administrație al unității de învățământ, apoi APROBAREA de către primar. Distincția aviz/aprobare contează: avizul este o opinie a organului deliberativ al școlii, aprobarea este actul care condiționează încheierea contractului.', 'avansat', 'clasificare'),
('Cine evaluează anual respectarea planului de management administrativ-financiar și cui aparține hotărârea finală privind eliberarea din funcție?', 'Autoritatea publică locală evaluează și tot ea decide eliberarea din funcție', 'Autoritatea publică locală evaluează și poate propune eliberarea, dar hotărârea finală aparține DJIP/DMBIP', 'Consiliul de administrație al unității evaluează, iar primarul decide', 'Ministerul Educației evaluează și decide', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 196 alin. (7)', 'Legislație', 'Art. 196 alin. (7) separă clar competențele: autoritatea publică locală efectuează anual evaluarea și poate PROPUNE consiliului de administrație al DJIP/DMBIP eliberarea din funcție, dar textul adaugă expres „Hotărârea finală aparține DJIP/DMBIP". Primarul nu poate elibera din funcție directorul, deși este parte în contractul administrativ-financiar.', 'avansat', 'capcana'),
('Ce condiție trebuie îndeplinită înainte de încheierea contractului de management educațional?', 'Prezentarea unei evaluări medicale care atestă că persoana este aptă pentru funcția vizată', 'Absolvirea programului de formare în management școlar', 'Obținerea avizului consiliului profesoral', 'Depunerea unei declarații de avere', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 197', 'Legislație', 'Art. 197 prevede că acest contract „poate fi încheiat numai după prezentarea unei evaluări medicale care atestă faptul că persoana este aptă pentru funcția vizată". Programul de formare în management (art. 194 alin. 4) se urmează ÎN primul an al mandatului, deci după numire, nu înainte de contract.', 'mediu', 'recall'),
('Care dintre următorii participă la concurs cu statut de OBSERVATOR, potrivit art. 198 alin. (2)?', 'Reprezentanții mediului economic și de afaceri', 'Un reprezentant al elevilor desemnat de Consiliul Național al Elevilor', 'Specialiștii în psihometrie', 'Directorul general al DJIP/DMBIP', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 198 alin. (2)', 'Legislație', 'Art. 198 alin. (2) distinge două categorii. MEMBRI ai comisiei de concurs: reprezentanți ai mediului economic și de afaceri. OBSERVATORI: reprezentanți ai federațiilor sindicale reprezentative, un reprezentant al elevilor desemnat de Consiliul Național al Elevilor și un reprezentant desemnat de federațiile reprezentative ale asociațiilor de părinți. Capcana este varianta a): reprezentanții mediului economic sunt membri cu drepturi depline, nu observatori.', 'avansat', 'clasificare'),
('Cine constituie comisia de concurs pentru funcțiile de conducere din Palatul Național al Copiilor?', 'DJIP/DMBIP pe raza căreia funcționează', 'Ministerul Educației, prin ordin al ministrului', 'Consiliul de administrație al Palatului', 'Consiliul Național al Elevilor', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 198 alin. (1)', 'Legislație', 'Art. 198 alin. (1) prevede regula generală — DJIP/DMBIP numește comisia pentru unitățile de învățământ — și o excepție expresă: pentru Palatul Național al Copiilor comisia se constituie la nivelul Ministerului Educației, prin ordin al ministrului. Excepția se justifică prin subordonarea directă a instituției față de minister.', 'avansat', 'capcana'),
('În care dintre situațiile de eliberare din funcție a directorului este OBLIGATORIE realizarea unui audit de către DJIP/DMBIP?', 'La propunerea motivată a directorului general al DJIP/DMBIP', 'La propunerea motivată a 2/3 dintre membrii consiliului de administrație al unității', 'La propunerea consiliului profesoral, cu votul secret a 2/3 dintre membri', 'Pentru încălcarea cu vinovăție a obligațiilor din contractul de management', 'C', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 198 alin. (4)', 'Legislație', 'Art. 198 alin. (4) lit. c) este singura ipoteză în care legea impune un audit: „În această situație, este obligatorie realizarea unui audit de către DJIP/DMBIP". Rezultatele auditului se analizează în consiliul de administrație al DJIP/DMBIP, iar decizia de eliberare se emite în funcție de hotărârea acestuia. Capcana constă în confuzia dintre lit. b) — propunerea CA al unității, unde nu se cere audit — și lit. c) — propunerea consiliului profesoral, unde se cere.', 'avansat', 'capcana'),
('Ce majoritate și ce tip de vot sunt necesare pentru ca propunerea de eliberare din funcție să vină din partea consiliului profesoral?', 'Majoritate simplă, vot deschis', 'Votul secret a 2/3 dintre membri', 'Votul deschis a 2/3 dintre membri', 'Unanimitate, vot secret', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 198 alin. (4) lit. c)', 'Legislație', 'Art. 198 alin. (4) lit. c) cere expres „votul secret a 2/3 dintre membri". Prin comparație, lit. b), privind consiliul de administrație al unității, cere tot 2/3 dintre membri, dar fără a impune caracterul secret al votului.', 'mediu', 'recall'),
('În cazul vacantării funcției de director, până când poate dura conducerea interimară?', 'Până la organizarea concursului, dar nu mai târziu de sfârșitul anului școlar', 'Cel mult 6 luni, indiferent de organizarea concursului', 'Până la organizarea concursului, fără alt termen-limită', 'Cel mult 30 de zile', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 198 alin. (6)', 'Legislație', 'Art. 198 alin. (6) prevede o dublă limită: până la organizarea concursului, DAR nu mai târziu de sfârșitul anului școlar. Conducerea interimară este asigurată de un cadru didactic titular, numit prin detașare în interesul învățământului, prin decizia directorului general, cu avizul consiliului de administrație al DJIP/DMBIP și cu ACORDUL SCRIS al persoanei solicitate — acordul scris fiind o condiție ușor de omis.', 'avansat', 'capcana'),
('Din câți membri poate fi constituit consiliul de administrație al unei unități de învățământ de stat?', '5, 7 sau 9 membri', '7, 9 sau 11 membri', '9, 11 sau 13 membri', 'Un număr stabilit liber de consiliul profesoral', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 128 alin. (2)', 'Legislație', 'Consiliul de administrație este organul deliberativ de conducere al unității și este constituit din 7, 9 sau 11 membri, în funcție de efectivul de beneficiari primari. Numărul este întotdeauna impar, pentru a evita blocajele la vot.', 'mediu', 'recall'),
('Unei unități de învățământ cu 350 de beneficiari primari îi corespunde un consiliu de administrație format din:', '7 membri, cu cvorum de cel puțin 4', '9 membri, cu cvorum de cel puțin 5', '11 membri, cu cvorum de cel puțin 6', '9 membri, cu cvorum de cel puțin 6', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 128 alin. (2) lit. a)-c)', 'Legislație', 'Pragurile sunt: sub 300 de beneficiari — 7 membri, cvorum minimum 4; între 301 și 400 — 9 membri, cvorum minimum 5; peste 400 — 11 membri, cvorum minimum 6. Un efectiv de 350 se încadrează în intervalul 301-400. Capcana o constituie asocierea greșită dintre numărul de membri și cvorum, cele două crescând în paralel.', 'avansat', 'capcana'),
('Care este componența consiliului de administrație format din 7 membri?', 'Directorul, 3 cadre didactice, 2 reprezentanți ai părinților, primarul', 'Directorul, 2 cadre didactice, 2 reprezentanți ai părinților, primarul sau un reprezentant al primarului, un reprezentant al consiliului local', 'Directorul, directorul adjunct, 2 cadre didactice, 2 părinți, primarul', 'Directorul, 2 cadre didactice, 3 reprezentanți ai părinților, primarul', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 128 alin. (2) lit. a)', 'Legislație', 'Formula de 7 membri este: directorul, 2 cadre didactice, 2 reprezentanți ai părinților, primarul sau un reprezentant al primarului și un reprezentant al consiliului local. Se observă echilibrul: 3 din partea școlii, 2 din partea părinților, 2 din partea autorității locale. La 9 și 11 membri crește atât numărul cadrelor didactice, cât și cel al reprezentanților consiliului local și ai părinților.', 'avansat', 'clasificare'),
('În consiliile de administrație de 9 sau 11 membri, cine poate ocupa unul dintre locurile repartizate cadrelor didactice?', 'Un reprezentant al personalului didactic auxiliar', 'Un reprezentant al personalului nedidactic', 'Un reprezentant al sindicatului', 'Directorul adjunct, de drept', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 128 alin. (2) lit. b)-c)', 'Legislație', 'Atât la formula de 9 membri (3 cadre didactice), cât și la cea de 11 membri (4 cadre didactice), legea precizează că „un reprezentant poate fi un reprezentant al personalului didactic auxiliar". Este o posibilitate, nu o obligație. Personalul nedidactic nu are loc rezervat în consiliul de administrație.', 'avansat', 'recall'),
('În consiliile de administrație ale unităților de nivel liceal/postliceal, reprezentantul elevilor cu drept de vot:', 'Ocupă un loc suplimentar, peste numărul de 7, 9 sau 11 membri', 'Ocupă un loc din cota aferentă părinților și trebuie să fi împlinit 18 ani', 'Participă doar cu statut de observator, fără drept de vot', 'Ocupă un loc din cota aferentă cadrelor didactice', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 128 alin. (2) lit. d)', 'Legislație', 'Art. 128 alin. (2) lit. d) prevede că, în unitățile de nivel liceal/postliceal, din cota aferentă PĂRINȚILOR un loc este repartizat, CU DREPT DE VOT, unui reprezentant al elevilor care a împlinit 18 ani. Nu este un loc suplimentar — reduce numărul locurilor părinților. Condiția de vârstă este esențială, fiind legată de capacitatea deplină de exercițiu.', 'avansat', 'capcana'),
('În unitățile care școlarizează DOAR nivel postliceal, cui revine cota aferentă părinților în consiliul de administrație?', 'Rămâne părinților', 'Revine reprezentanților elevilor', 'Revine cadrelor didactice', 'Revine operatorilor economici parteneri', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 128 alin. (2) lit. e)', 'Legislație', 'Art. 128 alin. (2) lit. e) prevede că, în unitățile care școlarizează doar nivel postliceal, cota aferentă părinților revine integral reprezentanților elevilor. Soluția este logică: elevii din învățământul postliceal sunt majori, deci reprezentarea prin părinți nu mai are sens. Se distinge de lit. d), unde doar UN loc din cota părinților trece la elevi.', 'avansat', 'clasificare'),
('În unitățile care organizează învățământ liceal tehnologic și postliceal, ce prevede legea în privința operatorilor economici parteneri?', 'Pot participa doar ca observatori', 'Consiliul de administrație se poate mări cu 2 membri desemnați de ei, iar unul dintre aceștia poate fi președinte al consiliului', 'Pot desemna un singur membru, fără drept de a fi președinte', 'Nu au niciun rol în consiliul de administrație', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 128 alin. (2) lit. f)', 'Legislație', 'Art. 128 alin. (2) lit. f) permite mărirea consiliului cu 2 membri desemnați de operatorii economici parteneri, asociațiile profesionale sau consorțiile partenere, iar reprezentantul unuia dintre operatorii economici POATE avea calitatea de președinte al consiliului de administrație. Este o excepție notabilă de la regula conducerii de către director, justificată de legătura învățământului tehnologic cu piața muncii.', 'avansat', 'capcana'),
('Cum este ales președintele consiliului de administrație?', 'Este de drept directorul unității', 'Este ales dintre membrii consiliului, cu majoritate simplă a voturilor', 'Este desemnat de primar', 'Este numit de inspectorul școlar general', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 128 alin. (2) lit. f)', 'Legislație', 'Legea prevede că „Președintele consiliului de administrație este ales dintre membrii acestuia cu majoritate simplă a voturilor". Directorul nu este, așadar, președinte de drept — el este membru al consiliului și poate fi ales președinte, dar la fel poate fi ales un alt membru, inclusiv un reprezentant al unui operator economic, în cazul unităților cu învățământ tehnologic.', 'mediu', 'recall'),
('Care dintre următoarele structuri NU este menționată de lege printre cele cu care conlucrează consiliile de administrație și directorii?', 'Comisia pentru Evaluarea și Asigurarea Calității (CEAC)', 'Comisia pentru Formare și Dezvoltare în Cariera Didactică (CFDCD)', 'Consiliul școlar al elevilor', 'Corpul Managerilor Educaționali', 'D', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 128 alin. (1)', 'Legislație', 'Art. 128 alin. (1) enumeră: CEAC, CFDCD, consiliul profesoral, autoritățile administrației publice locale, consiliul reprezentativ al părinților și asociațiile de părinți, organizațiile sindicale afiliate federațiilor reprezentative și consiliul școlar al elevilor. Corpul Managerilor Educaționali este o structură reală, înființată prin art. 194 alin. (7), dar are rol de mentorat pentru directori, nu de partener instituțional al consiliului de administrație.', 'mediu', 'clasificare'),
('Cum este compus consiliul profesoral și cine îl prezidează?', 'Din cadrele didactice titulare, prezidat de un cadru didactic ales', 'Din totalitatea cadrelor didactice din unitate, prezidat de director', 'Din cadrele didactice și personalul didactic auxiliar, prezidat de directorul adjunct', 'Din șefii de catedră, prezidat de director', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 129 alin. (1)', 'Legislație', 'Art. 129 alin. (1) prevede că este format din TOTALITATEA cadrelor didactice din unitatea de învățământ și este prezidat de către director. Nu se limitează la titulari și nu include personalul didactic auxiliar.', 'usor', 'recall'),
('Cât de des se întrunește consiliul profesoral și la solicitarea cui poate fi convocat?', 'Semestrial, doar la propunerea directorului', 'Lunar sau ori de câte ori este nevoie, la propunerea directorului sau la solicitarea a minimum o treime dintre membri', 'Lunar, exclusiv la convocarea directorului', 'Trimestrial, la solicitarea majorității membrilor', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 129 alin. (1)', 'Legislație', 'Art. 129 alin. (1) stabilește ritmul LUNAR, cu posibilitatea convocării ori de câte ori este nevoie, fie la propunerea directorului, fie la solicitarea a minimum O TREIME dintre membri. Pragul de o treime este important: permite cadrelor didactice să convoace consiliul chiar împotriva voinței directorului.', 'avansat', 'capcana'),
('Care dintre următoarele atribuții aparține consiliului profesoral ca decizie proprie, nu ca simplă propunere către consiliul de administrație?', 'Fișele de evaluare a personalului angajat', 'Curriculumul la decizia elevului din oferta școlii', 'Aprobarea sancționării abaterilor disciplinare ale elevilor', 'Programele de formare și dezvoltare profesională continuă', 'C', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 129 alin. (2)', 'Legislație', 'Art. 129 alin. (2) folosește verbe diferite, iar distincția este exact miza întrebării. Consiliul profesoral PROPUNE consiliului de administrație fișele de evaluare, măsurile de optimizare, curriculumul la decizia elevului, premierea, programele de formare. În schimb, el APROBĂ sancționarea abaterilor disciplinare ale elevilor (lit. g) și GESTIONEAZĂ calitatea actului didactic (lit. a) — acestea sunt competențe proprii.', 'avansat', 'capcana'),
('Ce rol are consiliul profesoral în privința Codului de etică profesională?', 'Îl elaborează integral, fără raportare la un cadru superior', 'Îl stabilește și monitorizează aplicarea lui, în conformitate cu codul-cadru aprobat prin ordin al ministrului educației', 'Doar îl aduce la cunoștința cadrelor didactice', 'Nu are atribuții în această materie', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 129 alin. (2) lit. b)', 'Legislație', 'Art. 129 alin. (2) lit. b) prevede că acest consiliu „stabilește și monitorizează aplicarea Codului de etică profesională elaborat în conformitate cu codul-cadru de etică profesională aprobat prin ordin al ministrului educației". Autonomia școlii este așadar limitată: codul propriu trebuie să se încadreze în codul-cadru național.', 'mediu', 'recall'),
('Care sunt componentele finanțării unităților de învățământ preuniversitar de stat, potrivit art. 138 alin. (1)?', 'Finanțarea de bază, finanțarea complementară și finanțarea suplimentară', 'Finanțarea de bază, finanțarea complementară și finanțarea specială', 'Finanțarea de bază și finanțarea complementară', 'Finanțarea de la bugetul de stat și finanțarea de la bugetele locale', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. X, art. 138 alin. (1)', 'Legislație', 'Art. 138 alin. (1) enumeră trei componente: finanțarea de bază, finanțarea complementară și finanțarea SPECIALĂ. Capcana este varianta a): termenul „finanțare suplimentară" apărea în reglementarea anterioară și este frecvent reținut din obișnuință, dar Legea nr. 198/2023 folosește „finanțare specială".', 'avansat', 'capcana'),
('Pe ce bază se realizează finanțarea de bază și cum se determină reperul acesteia?', 'În baza costului standard per elev, determinat pentru fiecare nivel de învățământ, filieră și profil', 'În baza bugetului solicitat anual de fiecare unitate', 'În baza suprafeței construite a unității', 'În baza numărului de cadre didactice încadrate', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. X, art. 138 alin. (3)-(4)', 'Legislație', 'Art. 138 alin. (3) prevede că finanțarea de bază se face în baza și în limitele costului standard per elev/preșcolar/antepreșcolar, iar alin. (4) precizează că acest cost se determină pentru fiecare nivel de învățământ, filieră și profil. Mecanismul „finanțarea urmează elevul" explică de ce numărul de beneficiari este variabila critică pentru bugetul școlii.', 'mediu', 'recall'),
('Prin ce buget se asigură cheltuielile cu salariile personalului din învățământul preuniversitar, ca parte a finanțării de bază?', 'Prin bugetele locale, din sume defalcate din unele venituri ale bugetului de stat', 'Prin bugetul Ministerului Educației', 'Prin bugetul propriu al unității de învățământ', 'Prin bugetul consiliului județean', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. X, art. 139 alin. (2)', 'Legislație', 'Art. 139 alin. (2) lit. a) prevede că cheltuielile cu salariile, sporurile, indemnizațiile și contribuțiile aferente se asigură PRIN BUGETUL MINISTERULUI EDUCAȚIEI. Capcana: alte componente ale finanțării de bază — formarea continuă (lit. b) și bunurile și serviciile (lit. c) — se asigură prin bugetele locale, din sume defalcate. Sursa diferă în funcție de categoria de cheltuială, în cadrul aceleiași finanțări de bază.', 'avansat', 'capcana'),
('Cheltuielile cu formarea continuă și cele cu bunuri și servicii se asigură:', 'Prin bugetul Ministerului Educației', 'Din sume defalcate din unele venituri ale bugetului de stat, prin bugetele locale', 'Din venituri proprii ale unității de învățământ', 'Din finanțarea complementară', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. X, art. 139 alin. (2) lit. b)-c)', 'Legislație', 'Art. 139 alin. (2) lit. b) și c) prevăd ambele categorii ca fiind acoperite din sume defalcate din unele venituri ale bugetului de stat, prin bugetele locale. Ele rămân parte din finanțarea DE BAZĂ, chiar dacă circuitul bugetar trece prin autoritatea locală — de aceea varianta d) este greșită.', 'avansat', 'clasificare'),
('Ce acoperă finanțarea complementară și din ce surse se asigură?', 'Cheltuieli de capital, cheltuieli sociale și alte cheltuieli care nu fac parte din finanțarea de bază; din bugetele locale și sume defalcate din bugetul de stat', 'Salariile personalului didactic; din bugetul Ministerului Educației', 'Exclusiv burse și ajutoare sociale; din venituri proprii', 'Costul standard per elev; din bugetul de stat', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. X, art. 140 alin. (1)-(2)', 'Legislație', 'Art. 140 alin. (1) definește finanțarea complementară ca asigurând cheltuieli de capital, cheltuieli sociale și alte cheltuieli asociate procesului de învățământ care nu fac parte din finanțarea de bază. Alin. (2) precizează sursele: bugetele locale ale unităților administrativ-teritoriale de care aparțin școlile și sume defalcate din unele venituri ale bugetului de stat, aprobate anual prin legea bugetului.', 'mediu', 'recall'),
('Care dintre următoarele categorii de cheltuieli intră în finanțarea COMPLEMENTARĂ?', 'Salariile cadrelor didactice', 'Investiții, reparații capitale și curente, consolidări', 'Cheltuielile cu formarea continuă a personalului', 'Cheltuielile cu bunuri și servicii curente', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. X, art. 140 alin. (2)', 'Legislație', 'Art. 140 alin. (2) lit. a) include investițiile, reparațiile capitale și curente și consolidările în finanțarea complementară, alături de subvențiile pentru internate și cantine (lit. b), cheltuielile pentru evaluarea periodică națională a elevilor (lit. c) și cele pentru examinarea medicală obligatorie periodică a salariaților (lit. d). Salariile, formarea continuă și bunurile și serviciile aparțin finanțării DE BAZĂ, potrivit art. 139.', 'avansat', 'clasificare'),
('Cheltuielile pentru examinarea medicală obligatorie periodică a salariaților din învățământul preuniversitar se suportă:', 'Din finanțarea de bază', 'Din finanțarea complementară', 'De către fiecare salariat', 'Din fondul de asigurări sociale de sănătate', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. X, art. 140 alin. (2) lit. d)', 'Legislație', 'Art. 140 alin. (2) lit. d) plasează expres aceste cheltuieli în finanțarea complementară. Corelația utilă: art. 219 alin. (2) garantează personalului asistență medicală gratuită pentru examinările periodice — dreptul este prevăzut în Titlul III, iar sursa de finanțare în Titlul I.', 'avansat', 'capcana'),
('Cărui domeniu de competență îi aparține „managementul schimbării, adaptare și gestionarea presiunilor"?', 'Domeniul 1 — Leadership educațional, guvernanță instituțională și orientare strategică', 'Domeniul 2 — Management operațional administrativ-financiar și conformitate', 'Domeniul 3 — Managementul calității și evaluare internă', 'Domeniul 5 — Comunicare, relaționare, parteneriate și colaborare în comunitate', 'A', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II lit. C, domeniul 1', 'Profilul managerului școlar', 'Competența 1.1 „Managementul schimbării, adaptare și gestionarea presiunilor" deschide domeniul 1, alături de 1.2 dezvoltare și transformare organizațională, 1.3 leadership incluziv, stare de bine, securitate și siguranță școlară și 1.4 aderarea la principii și valori.', 'mediu', 'clasificare'),
('Unde este plasată în profil competența privind „starea de bine a elevilor și a personalului școlii, securitate și siguranță școlară"?', 'În domeniul 2, alături de managementul riscului', 'În domeniul 1, ca parte a competenței privind leadershipul incluziv', 'În domeniul 3, la managementul incluziunii', 'În domeniul 5, la relaționare și gestionarea conflictelor', 'B', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II lit. C, domeniul 1', 'Profilul managerului școlar', 'Competența 1.3 se numește „Leadership incluziv, stare de bine a elevilor și a personalului școlii, securitate și siguranță școlară" și aparține domeniului 1. Capcana e reală: profilul conține și competența 2.2 „Reziliență și managementul riscului" (domeniul 2) și 3.3 „Managementul incluziunii și al diversității în profilurile de învățare" (domeniul 3), teme învecinate, dar distincte.', 'avansat', 'capcana'),
('Competența „Conformitate juridică și etică profesională" aparține domeniului:', '1 — Leadership educațional și orientare strategică', '2 — Management operațional administrativ-financiar și conformitate', '3 — Managementul calității și evaluare internă', '4 — Managementul curriculumului', 'B', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II lit. C, domeniul 2', 'Profilul managerului școlar', 'Competența 2.1 „Conformitate juridică și etică profesională" deschide domeniul 2, care mai cuprinde 2.2 reziliență și managementul riscului, 2.3 identitate digitală, inovare și eficiență managerială și 2.4 prezentarea și comunicarea informațiilor. Denumirea domeniului conține chiar cuvântul „conformitate", ceea ce ajută la memorare.', 'mediu', 'clasificare'),
('Ce competențe specifice cuprinde domeniul 3 — Managementul calității și evaluare internă?', 'Monitorizare și evaluare internă; responsabilitate publică; managementul incluziunii și diversității; colectarea datelor și strategii de îmbunătățire', 'Managementul resurselor umane; implementarea curriculumului; cercetare pedagogică; succesul școlar', 'Conformitate juridică; managementul riscului; identitate digitală; comunicarea informațiilor', 'Relaționare și conflicte; rețele și proiecte; antreprenoriat educațional; resurse extrabugetare', 'A', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II lit. C, domeniul 3', 'Profilul managerului școlar', 'Domeniul 3 cuprinde 3.1 monitorizare, evaluare internă și raportare; 3.2 responsabilitate publică și relaționare instituțională; 3.3 managementul incluziunii și al diversității în profilurile de învățare; 3.4 colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității. Variantele b), c) și d) descriu exact domeniile 4, 2 și respectiv 5.', 'mediu', 'recall'),
('„Atragerea de resurse extrabugetare" este o competență specifică din domeniul:', '2 — Management operațional administrativ-financiar și conformitate', '5 — Comunicare, relaționare, parteneriate și colaborare în comunitate', '1 — Leadership educațional și orientare strategică', '3 — Managementul calității și evaluare internă', 'B', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II lit. C, domeniul 5', 'Profilul managerului școlar', 'Competența 5.4 „Atragerea de resurse extrabugetare" încheie domeniul 5, alături de 5.1 relaționare, comunicare și gestionarea conflictelor, 5.2 participarea la rețele și proiecte naționale și internaționale și 5.3 antreprenoriat educațional și inovație. Capcana: deși vorbim despre resurse financiare, profilul o plasează la comunicare și parteneriate, nu la managementul administrativ-financiar — pentru că atragerea de fonduri depinde de relația cu comunitatea.', 'mediu', 'clasificare'),
('Câte competențe specifice sunt asociate fiecărui domeniu de competență din profil?', 'Două', 'Trei', 'Patru', 'Număr variabil, între două și șase', 'C', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II lit. C', 'Profilul managerului școlar', 'Fiecare dintre cele cinci domenii are exact patru competențe specifice, numerotate x.1 - x.4, ceea ce dă 20 de competențe specifice în total. Structura simetrică ajută la memorare și la orientarea în grila de evaluare.', 'mediu', 'recall'),
('Cum descrie profilul impactul directorului asupra rezultatelor elevilor?', 'Direct asupra rezultatelor elevilor și indirect asupra culturii organizaționale', 'Direct asupra culturii organizaționale și indirect, dar esențial, asupra calității predării și rezultatelor elevilor', 'Direct atât asupra culturii, cât și asupra rezultatelor', 'Fără impact măsurabil asupra rezultatelor elevilor', 'B', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul I — Context', 'Profilul managerului școlar', 'Profilul formulează exact invers față de intuiția comună: impactul directorului „este direct asupra culturii organizaționale și indirect, dar esențial, asupra calității predării, echității educaționale și rezultatelor elevilor". Ideea se corelează cu literatura de specialitate — inclusiv cu Hattie — potrivit căreia liderul școlar acționează asupra învățării prin mediere, nu nemijlocit.', 'avansat', 'capcana'),
('Ce nevoie structurală a sistemului educațional urmărește să acopere profilul managerului școlar?', 'Reducerea numărului de funcții de conducere', 'Transformarea funcției de conducere dintr-un rol predominant administrativ într-un rol profesionalizat, bazat pe competențe demonstrabile și impact măsurabil', 'Uniformizarea salarizării directorilor', 'Creșterea autonomiei financiare a unităților', 'B', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul I — Context', 'Profilul managerului școlar', 'Capitolul I formulează explicit această finalitate. Cele două criterii — competențe DEMONSTRABILE și impact MĂSURABIL — explică de ce documentul se încheie cu descriptori comportamentali observabili, la nivelul funcțional.', 'mediu', 'recall'),
('Ce afirmă Concepția 3 din capitolul 9?', 'Profesorii și liderii vor să vorbească mai mult despre învățare decât despre predare', 'Profesorii și liderii vor să vorbească mai mult despre predare decât despre învățare', 'Profesorii și liderii evită discuțiile despre metodele proprii', 'Profesorii și liderii preferă discuțiile despre curriculum', 'A', 'Hattie, J., Învățarea vizibilă, Editura Polirom — Capitolul 9 — Concepția 3', 'Învățarea vizibilă (Hattie)', 'Concepția 3 inversează accentul obișnuit din cancelarie: discuția profesională trebuie centrată pe ÎNVĂȚARE — ce și cât au învățat elevii — nu pe predare, adică pe ceea ce a făcut adultul. Varianta b) formulează exact poziția criticată de autor.', 'mediu', 'recall'),
('Concepția 5 susține că profesorii și liderii:', 'Trebuie să transmită cât mai multă informație în timpul disponibil', 'Se angajează în dialog, nu în monolog', 'Trebuie să reducă interacțiunea verbală în favoarea lucrului individual', 'Trebuie să evite dezbaterile contradictorii în clasă', 'B', 'Hattie, J., Învățarea vizibilă, Editura Polirom — Capitolul 9 — Concepția 5', 'Învățarea vizibilă (Hattie)', 'Concepția 5 este formulată ca „Profesorii/liderii se angajează în dialog, nu în monolog". Capitolul recunoaște că profesorii trebuie să transmită și informații, dar critică dominația monologului. Legat de aceasta, textul discută și rolul ascultării — un anumit tip de ascultare fiind necesar pentru a înțelege cum și dacă elevii înțeleg.', 'mediu', 'clasificare'),
('Ce atitudine descrie Concepția 6?', 'Profesorii și liderii evită situațiile de risc pedagogic', 'Profesorii și liderii sunt deschiși la provocări și dau „tot ce e mai bun"', 'Profesorii și liderii se concentrează pe conformarea la proceduri', 'Profesorii și liderii deleagă provocările către specialiști externi', 'B', 'Hattie, J., Învățarea vizibilă, Editura Polirom — Capitolul 9 — Concepția 6', 'Învățarea vizibilă (Hattie)', 'Concepția 6 afirmă că profesorii și liderii „sunt deschiși la provocări și dau «tot ce e mai bun»". Capitolul pornește de la constatarea că viața de zi cu zi la clasă este o provocare permanentă, iar atitudinea față de aceasta — asumare, nu evitare — face diferența de impact.', 'mediu', 'recall'),
('Concepția 8 se referă la:', 'Informarea tuturor cu privire la limbajul învățării', 'Informarea părinților despre notele elevilor', 'Raportarea rezultatelor către inspectorat', 'Comunicarea publică a rezultatelor la evaluările naționale', 'A', 'Hattie, J., Învățarea vizibilă, Editura Polirom — Capitolul 9 — Concepția 8', 'Învățarea vizibilă (Hattie)', 'Concepția 8 afirmă că profesorii și liderii „îi informează pe toți cu privire la limbajul învățării". Este vorba despre un vocabular comun al învățării — împărtășit de profesori, elevi și părinți — nu despre raportarea administrativă a rezultatelor. Capitolul insistă că elevii trebuie să poată vorbi despre cât de bine au învățat, nu doar să primească note.', 'avansat', 'clasificare'),
('Ce conține Anexa A a capitolului?', 'O bibliografie adnotată a studiilor meta-analitice', 'O listă de control pentru școli, cu afirmații evaluate pe o scală', 'Tabelul complet al mărimilor de efect pentru toate influențele studiate', 'Un model de plan managerial', 'B', 'Hattie, J., Învățarea vizibilă, Editura Polirom — Capitolul 9 — Anexa A', 'Învățarea vizibilă (Hattie)', 'Anexa A este o listă de control pentru școli, structurată pe teme — predarea motivată și pasionată, profesionalismul, familiarizarea cu curricula, planificarea, desfășurarea lecției și feedbackul — fiecare afirmație fiind evaluată pe o scală. Este instrumentul practic prin care școala își poate verifica „starea de sănătate" a învățării vizibile.', 'mediu', 'recall'),
('Ce avertisment formulează Bush în legătură cu distincția dintre leadership și management?', 'Că managementul este superior leadershipului în școlile publice', 'Că nu trebuie construită o dihotomie simplistă între un „leadership" valorizat și un „management" devalorizat', 'Că cele două noțiuni sunt perfect sinonime', 'Că leadershipul este relevant doar în sistemele descentralizate', 'B', 'Bush, T., Leadership și management educațional, Editura Polirom — Capitolul 1 — Importanța leadershipului și a managementului educațional', 'Leadership educațional (Bush)', 'Bush respinge opoziția facilă dintre „leadership" tratat ca nobil și „management" tratat ca ceva „murdar", ori între valori și scopuri, pe de o parte, și proceduri, pe de altă parte. Argumentul lui este că ambele funcții sunt necesare pentru buna funcționare a școlii, chiar dacă analitic pot fi distinse.', 'avansat', 'capcana'),
('Ce condiție suplimentară prevede legea pentru candidații din învățământul vocațional teologic?', 'Absolvirea unui masterat în teologie', 'Obținerea avizului cultului', 'Vechime de minimum 10 ani în învățământul confesional', 'Recomandarea consiliului profesoral', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 196 alin. (3)', 'Legislație', 'Art. 196 alin. (3) lit. d) cere obținerea avizului cultului, în cazul învățământului vocațional teologic. Condiția se adaugă celor generale — diplomă de licență sau atestat de echivalare, vechime de cel puțin 5 ani și lipsa unei condamnări pentru fapte incompatibile cu funcția didactică. Se corelează cu documentul justificativ privind avizul cultului religios, cerut la dosarul de înscriere potrivit Metodologiei.', 'avansat', 'clasificare'),
('Din ce este constituit sistemul național de învățământ preuniversitar și cum se înființează unitățile?', 'Doar din unități de stat; se înființează prin hotărâre a consiliului local', 'Din unități de stat, particulare și confesionale autorizate provizoriu/acreditate; se înființează prin ordin al ministrului educației', 'Din unități de stat și particulare; se înființează prin hotărâre de Guvern', 'Din unități acreditate exclusiv; se înființează prin decizie a inspectoratului școlar', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. II, art. 12 alin. (1)-(2)', 'Legislație', 'Art. 12 alin. (1) include cele trei categorii — de stat, particulare și confesionale — cu condiția de a fi autorizate să funcționeze provizoriu sau acreditate. Alin. (2) prevede înființarea pe niveluri de învățământ, prin ordin al ministrului educației. Autorizarea provizorie este suficientă pentru apartenența la sistem; acreditarea nu este obligatorie.', 'mediu', 'recall'),
('Ce cuprinde învățământul obligatoriu potrivit art. 13 alin. (1)?', 'Învățământul primar și gimnazial', 'Învățământul preșcolar, primar, gimnazial și liceal', 'Învățământul antepreșcolar, preșcolar, primar și gimnazial', 'Învățământul primar, gimnazial și liceal', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. II, art. 13 alin. (1)', 'Legislație', 'Art. 13 alin. (1) include patru niveluri: preșcolar, primar, gimnazial și liceal. Capcanele sunt la ambele capete: învățământul ANTEPREȘCOLAR nu este obligatoriu, dar cel PREȘCOLAR este, iar învățământul liceal a fost inclus în obligativitate — element de noutate față de reglementările anterioare.', 'avansat', 'capcana'),
('În ce condiții poate fi dispusă exmatricularea pe perioada învățământului obligatoriu?', 'Este interzisă în orice situație', 'Numai în situații grave, în urma încălcării normelor de disciplină în spațiul școlar, pentru protejarea dreptului la educație al celorlalți beneficiari', 'La decizia discreționară a directorului', 'După trei absențe nemotivate consecutive', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. II, art. 13 alin. (2)', 'Legislație', 'Art. 13 alin. (2) permite exmatricularea doar în situații grave, ca urmare a încălcării normelor de disciplină în spațiul școlar, iar rațiunea invocată expres de lege este protejarea dreptului la educație al celorlalți beneficiari primari. Este o măsură excepțională, supusă unei proceduri, nu o sancțiune uzuală.', 'avansat', 'recall'),
('Ce cuprinde rețeaua școlară, potrivit art. 19 alin. (1)?', 'Doar unitățile de învățământ acreditate', 'Unitățile autorizate provizoriu și acreditate, cele înființate în structura instituțiilor de învățământ superior și unitățile de educație extrașcolară', 'Doar unitățile de învățământ de stat', 'Unitățile de învățământ preuniversitar și universitățile', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. III, art. 19 alin. (1)', 'Legislație', 'Art. 19 alin. (1) enumeră trei categorii: unitățile autorizate provizoriu și cele acreditate; unitățile de învățământ preuniversitar înființate în structura sau în subordinea instituțiilor de învățământ superior; unitățile de educație extrașcolară, între care cluburile sportive școlare. Universitățile ca atare nu fac parte din rețeaua școlară preuniversitară.', 'mediu', 'clasificare'),
('Cum definește legea incluziunea în contextul educației?', 'Ca simplă înscriere a elevilor cu dizabilități în învățământul de masă', 'Ca proces și măsuri complexe prin care sunt asigurate cadrul și condițiile pentru atingerea finalităților educaționale, punând accentul pe respectarea dreptului la educație al fiecărui copil', 'Ca obligație exclusivă a învățământului special', 'Ca program finanțat din fonduri europene', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. V, art. 67 alin. (1)', 'Legislație', 'Art. 67 alin. (1) definește incluziunea ca proces și ansamblu de măsuri complexe, având în centru respectarea dreptului la educație al fiecărui copil, și vizând dezvoltarea comportamentelor adaptative și a abilităților cognitive. Statul GARANTEAZĂ dreptul la o educație incluzivă de calitate tuturor beneficiarilor primari — deci nu este o măsură limitată la o categorie.', 'mediu', 'recall'),
('Care este finalitatea principală a învățământului preuniversitar, potrivit art. 85 alin. (1)?', 'Promovarea examenelor naționale', 'Formarea competențelor, înțelese ca ansamblu multifuncțional și transferabil de cunoștințe, abilități și atitudini', 'Transmiterea unui volum determinat de cunoștințe', 'Orientarea profesională a elevilor', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. VI, art. 85 alin. (1)', 'Legislație', 'Art. 85 alin. (1) definește finalitatea ca formarea competențelor, cu accent pe caracterul MULTIFUNCȚIONAL și TRANSFERABIL al ansamblului de cunoștințe, abilități și atitudini. Competențele sunt necesare pentru împlinirea și dezvoltarea personală, integrarea socială și participarea cetățenească, participarea la o economie durabilă și formarea unei concepții de viață.', 'mediu', 'recall'),
('Ce prevede legea în privința efectelor modificării planurilor-cadru?', 'Modificările intră în vigoare imediat după aprobare', 'Modificările nu produc efecte în timpul anului școlar în curs', 'Modificările se aplică doar începând cu clasa pregătitoare', 'Planurile-cadru nu pot fi modificate', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. VI, art. 86 alin. (1)', 'Legislație', 'Art. 86 alin. (1) prevede că planurile-cadru se evaluează și, după caz, se revizuiesc periodic, dar „modificările nu vor produce efecte în timpul anului școlar în curs". Regula protejează predictibilitatea parcursului școlar și este relevantă direct pentru director, care răspunde de aplicarea planurilor-cadru.', 'avansat', 'capcana'),
('Din ce se constituie trunchiul comun?', 'Din disciplinele opționale alese de elev', 'Din disciplinele, domeniile de studiu și modulele de pregătire obligatorii pentru toți elevii', 'Din disciplinele de examen la evaluările naționale', 'Din orele de pregătire suplimentară', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. VI, art. 86 alin. (1)-(2)', 'Legislație', 'Art. 86 alin. (2) definește trunchiul comun ca fiind format din disciplinele/domeniile de studiu/modulele de pregătire OBLIGATORII pentru toți elevii. Planurile-cadru cuprind atât elemente obligatorii, cât și opționale, împreună cu bugetul de timp alocat — trunchiul comun este partea obligatorie.', 'mediu', 'clasificare'),
('Care sunt scopurile evaluării, potrivit art. 95 alin. (1)?', 'Ierarhizarea elevilor și selecția pentru treapta următoare', 'Orientarea și optimizarea procesului de predare-învățare, precum și gestionarea propriilor rezultate ale învățării', 'Raportarea statistică la nivel național', 'Evaluarea activității cadrelor didactice', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. VII, art. 95 alin. (1)', 'Legislație', 'Art. 95 alin. (1) stabilește două scopuri: orientarea și optimizarea procesului de predare-învățare și gestionarea de către elev a propriilor rezultate. Formularea este apropiată de perspectiva lui Hattie, unde evaluarea este feedback despre impact, nu instrument de clasificare. Toate evaluările se realizează pe baza standardelor naționale de evaluare (alin. 2).', 'mediu', 'recall'),
('Cum se exprimă rezultatele evaluării în învățământul primar?', 'Prin note de la 1 la 10, inclusiv în clasa pregătitoare', 'Prin calificative, cu excepția clasei pregătitoare, pe parcursul căreia nu se acordă note sau calificative', 'Prin calificative, inclusiv în clasa pregătitoare', 'Prin punctaje specifice', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. VII, art. 96 alin. (1)', 'Legislație', 'Art. 96 alin. (1) lit. a) prevede calificativele „foarte bine", „bine", „suficient" sau „insuficient" pentru învățământul primar, EXCEPTÂND clasa pregătitoare, unde nu se acordă nici note, nici calificative. Capcana este varianta c): excepția clasei pregătitoare este ușor de omis. În gimnazial, liceal și postliceal se folosesc note de la 1 la 10.', 'avansat', 'capcana'),
('Cine sunt beneficiarii SECUNDARI ai învățământului preuniversitar?', 'Elevii și preșcolarii', 'Părinții, tutorii sau reprezentanții legali', 'Comunitatea locală și societatea în ansamblul ei', 'Cadrele didactice', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. VIII, art. 105', 'Legislație', 'Art. 105 stabilește trei categorii: beneficiari PRIMARI — antepreșcolarii, preșcolarii, elevii și persoanele adulte înscrise; beneficiari SECUNDARI — părinții, tutorii sau reprezentanții legali; beneficiari TERȚIARI — comunitatea locală și societatea în ansamblu. Terminologia apare constant în lege și în metodologii, inclusiv la stabilirea numărului de membri ai consiliului de administrație, calculat pe „beneficiari primari".', 'mediu', 'clasificare'),
('Persoanele adulte înscrise într-o unitate de învățământ sunt considerate:', 'Beneficiari primari', 'Beneficiari secundari', 'Beneficiari terțiari', 'Nu sunt încadrate în nicio categorie', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. VIII, art. 105 alin. (1)', 'Legislație', 'Art. 105 alin. (1) include expres „persoanele adulte înscrise într-o unitate de învățământ" printre beneficiarii PRIMARI, alături de antepreșcolari, preșcolari și elevi. Capcana este asocierea automată dintre „primar" și „copil": criteriul nu este vârsta, ci calitatea de destinatar direct al actului educațional.', 'avansat', 'capcana'),
('Ce calitate are Ministerul Educației potrivit art. 115 alin. (1)?', 'Organ de specialitate al administrației publice centrale, care elaborează și implementează politica națională în domeniul învățământului preuniversitar', 'Autoritate administrativă autonomă', 'Structură de coordonare fără drept de inițiativă financiară', 'Organism consultativ al Guvernului', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 115 alin. (1)', 'Legislație', 'Art. 115 alin. (1) definește Ministerul Educației ca organ de specialitate al administrației publice centrale, care elaborează și implementează politica națională în învățământul preuniversitar și are drept de inițiativă ȘI de execuție în domeniul politicii financiare și al resurselor umane din educație. Tot art. 115 alin. (2) lit. m) este temeiul invocat în preambulul Metodologiei concursului.', 'mediu', 'recall'),
('Ce amendă contravențională prevede legea pentru interzicerea, din culpa părintelui, a participării beneficiarului la programul școlar?', 'De la 100 la 1.000 de lei', 'De la 1.000 la 5.000 de lei', 'De la 5.000 la 10.000 de lei', 'De la 500 la 2.500 de lei', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. XI, art. 148 alin. (1) lit. a)', 'Legislație', 'Art. 148 alin. (1) lit. a) sancționează fapta cu amendă de la 1.000 de lei la 5.000 de lei, în măsura în care nu constituie infracțiune. Aceeași sancțiune se aplică și în cazul refuzului semnării contractului educațional. Directorul trebuie să cunoască aceste prevederi pentru gestionarea absenteismului și a relației cu familia.', 'avansat', 'recall'),
('Pe ce perioadă maximă poate fi suspendat dreptul de înscriere la un concurs pentru obținerea gradației de merit sau pentru ocuparea unei funcții, ca sancțiune disciplinară?', 'Până la 1 an', 'Până la 2 ani', 'Până la 3 ani', 'Până la 5 ani', 'C', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XIV, art. 210 alin. (1) lit. c)', 'Legislație', 'Art. 210 alin. (1) lit. c) prevede suspendarea pe o perioadă de până la 3 ani. Sancțiunea este direct relevantă pentru concursul de directori: art. 3 alin. (1) lit. f) din Metodologie exclude candidatul care a fost sancționat disciplinar cu suspendarea dreptului de a se înscrie la un concurs pentru ocuparea unei funcții de conducere, dacă sancțiunea nu a fost radiată.', 'avansat', 'capcana'),
('Ce elemente sunt prevăzute în planurile-cadru de învățământ?', 'Doar disciplinele obligatorii', 'Disciplinele, domeniile de studiu, modulele de pregătire obligatorii și opționale, precum și bugetul de timp alocat acestora', 'Conținuturile detaliate ale fiecărei lecții', 'Standardele naționale de evaluare', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. VI, art. 86 alin. (1)', 'Legislație', 'Art. 86 alin. (1) enumeră disciplinele, domeniile de studiu, modulele de pregătire obligatorii ȘI opționale, împreună cu bugetul de timp alocat. Conținuturile detaliate aparțin programelor școlare, nu planurilor-cadru, iar standardele naționale de evaluare sunt reglementate separat, la art. 95 alin. (2).', 'mediu', 'recall'),
('Cum poate fi eliberat din funcție directorul unei unități de învățământ particular sau confesional?', 'Prin decizie a directorului general al DJIP/DMBIP', 'La propunerea consiliului de administrație, cu votul a 2/3 din membrii săi, prin decizia persoanei juridice fondatoare', 'Prin ordin al ministrului educației', 'Prin hotărâre a consiliului profesoral', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul III, cap. XI, art. 198 alin. (5)', 'Legislație', 'Art. 198 alin. (5) prevede o procedură distinctă pentru învățământul particular și confesional: propunerea vine de la consiliul de administrație, cu votul a 2/3 din membrii săi, iar actul de eliberare aparține persoanei juridice FONDATOARE. Diferența față de învățământul de stat reflectă regimul juridic diferit al fondatorului privat.', 'avansat', 'clasificare'),
('Ce natură juridică are consiliul de administrație al unității de învățământ de stat?', 'Organ consultativ', 'Organ deliberativ de conducere', 'Organ executiv', 'Organ de control financiar', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IX, art. 128 alin. (2)', 'Legislație', 'Art. 128 alin. (2) califică expres consiliul de administrație drept ORGANUL DELIBERATIV de conducere al unității de învățământ. Corelativ, art. 195 alin. (1) atribuie directorului conducerea EXECUTIVĂ. Distincția deliberativ/executiv este una dintre cele mai testabile din materie.', 'usor', 'recall'),
('Care dintre următoarele NU figurează printre competențele transversale ale managerului școlar?', 'Gândire critică, analitică și sistemică', 'Competențe de analiză cantitativă și utilizare a datelor', 'Atragerea de resurse extrabugetare', 'Inteligență emoțională, autoreglare și maturitate relațională', 'C', 'Profilul profesional al managerului școlar, OMEC nr. 3.934/2026 — Capitolul II lit. B — competențe transversale', 'Profilul managerului școlar', 'Atragerea de resurse extrabugetare este competența specifică 5.4, deci aparține nivelului PROFESIONAL (domeniul 5), nu celui transversal. Competențele transversale sunt precondiții cognitive, relaționale și profesionale: gândire critică și sistemică, raționament strategic, analiză cantitativă și utilizarea datelor, competențe digitale, competențe lingvistice, inteligență emoțională și leadership adaptativ.', 'avansat', 'clasificare'),
('Care sunt efectivele unei clase din învățământul primar?', 'În medie 18 elevi, minimum 12 și maximum 24', 'În medie 20 de elevi, minimum 12 și maximum 28', 'În medie 23 de elevi, minimum 16 și maximum 30', 'În medie 25 de elevi, minimum 15 și maximum 30', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. III, art. 23 alin. (1) lit. c)', 'Legislație', 'Art. 23 alin. (1) lit. c) stabilește pentru învățământul primar o medie de 18 elevi, cu minimum 12 și maximum 24. Variantele b) și c) reproduc exact cifrele pentru gimnaziu (20/12/28), respectiv liceu (23/16/30) — efectivele cresc progresiv odată cu nivelul, iar confuzia între ele este cea mai frecventă.', 'mediu', 'recall'),
('Care este efectivul MAXIM al unei clase de gimnaziu, respectiv de liceu?', '24 la gimnaziu, 28 la liceu', '28 la gimnaziu, 30 la liceu', '30 la gimnaziu, 32 la liceu', '28 la ambele', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. III, art. 23 alin. (1) lit. d) și f)', 'Legislație', 'Gimnaziul: în medie 20, minimum 12, maximum 28 (lit. d). Liceul, inclusiv cel dual: în medie 23, minimum 16, maximum 30 (lit. f). Pragurile sunt esențiale pentru director la constituirea formațiunilor de studiu și la fundamentarea proiectului planului de școlarizare.', 'avansat', 'capcana'),
('Pe ce grupe se desfășoară instruirea practică și pregătirea de specialitate?', 'Grupe de minimum 8 și maximum 15 elevi', 'Grupe de minimum 4 și maximum 10 elevi', 'Grupe de minimum 12 și maximum 24 de elevi', 'Nu există limite legale', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. III, art. 23 alin. (1) lit. g)-h)', 'Legislație', 'Art. 23 alin. (1) lit. g) prevede grupe de minimum 8 și maximum 15 elevi pentru instruirea practică și pregătirea de specialitate. Varianta b) reproduce efectivul grupei din învățământul sportiv și de artă (în medie 7, minimum 4, maximum 10), potrivit lit. e). Tot la lit. h), clasele din liceul tehnologic pot fi constituite din maximum 3 grupe cu calificări diferite.', 'avansat', 'clasificare'),
('Care sunt efectivele unei clase din învățământul postliceal?', 'În medie 20 de elevi, minimum 12 și maximum 28', 'În medie 26 de elevi, minimum 20 și maximum 32', 'În medie 23 de elevi, minimum 16 și maximum 30', 'În medie 30 de elevi, minimum 25 și maximum 35', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. III, art. 23 alin. (1) lit. i)', 'Legislație', 'Art. 23 alin. (1) lit. i) prevede pentru învățământul postliceal o medie de 26 de elevi, cu minimum 20 și maximum 32 — cele mai mari efective din sistem, explicabile prin faptul că elevii sunt adulți.', 'avansat', 'recall'),
('Ce vârste deservesc creșele și grădinițele ca unități de educație timpurie?', 'Antepreșcolari între 3 luni și 3 ani, respectiv preșcolari între 3 și 6 ani', 'Antepreșcolari între 1 și 2 ani, respectiv preșcolari între 2 și 5 ani', 'Exclusiv preșcolari între 3 și 6 ani', 'Copii între 6 luni și 7 ani, fără distincție pe niveluri', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IV, art. 30 alin. (1)', 'Legislație', 'Art. 30 alin. (1) stabilește intervalele: 3 luni - 3 ani pentru nivelul antepreșcolar și 3 - 6 ani pentru nivelul preșcolar. Creșele și grădinițele fac parte din sistemul național de învățământ preuniversitar și oferă servicii integrate de educație, cu evaluări anuale finalizate printr-un raport descriptiv de evaluare.', 'mediu', 'clasificare'),
('Ce condiție de vârstă trebuie îndeplinită pentru înscrierea în clasa pregătitoare?', 'Împlinirea vârstei de 6 ani până la 31 decembrie a anului în care se face înscrierea', 'Împlinirea vârstei de 6 ani până la 31 august a anului în care se face înscrierea', 'Împlinirea vârstei de 7 ani până la începerea anului școlar', 'Împlinirea vârstei de 5 ani până la 1 septembrie', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IV, art. 31 alin. (2)', 'Legislație', 'Art. 31 alin. (2) prevede înscrierea copiilor care au urmat învățământul preșcolar și împlinesc 6 ani până la 31 AUGUST în anul înscrierii. Data de 31 decembrie, din varianta a), corespunde unor reglementări anterioare și este capcana clasică. Înscrierea se face potrivit unei metodologii aprobate prin ordin de ministru.', 'avansat', 'capcana'),
('Ce clase cuprinde învățământul primar, respectiv cel gimnazial?', 'Primar: clasele I-IV; gimnazial: clasele V-IX', 'Primar: clasa pregătitoare și clasele I-IV; gimnazial: clasele V-VIII', 'Primar: clasele I-V; gimnazial: clasele VI-VIII', 'Primar: clasa pregătitoare și clasele I-V; gimnazial: clasele VI-IX', 'B', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IV, art. 31 alin. (1) și art. 32 alin. (1)', 'Legislație', 'Art. 31 alin. (1) include în învățământul primar clasa pregătitoare și clasele I-IV, iar art. 32 alin. (1) definește gimnaziul ca ansamblul claselor V-VIII. Ambele niveluri funcționează, de regulă, cu program de dimineață — pentru primar, obligatoriu începând cu anul școlar 2029-2030, iar pentru clasa a VIII-a, începând cu anul 2030.', 'mediu', 'clasificare'),
('Ce tip de program este prevăzut expres pentru încurajarea finalizării învățământului obligatoriu la nivel gimnazial?', 'Programe de tip „Școala după școală"', 'Programe de tip „A doua șansă"', 'Programe de mentorat individual', 'Programe de învățământ dual', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IV, art. 32 alin. (2)', 'Legislație', 'Art. 32 alin. (2) prevede că, pentru încurajarea finalizării învățământului obligatoriu, elevii pot participa la programe de tip „Școala după școală" dedicate învățământului gimnazial. Programul „A doua șansă" se adresează persoanelor care au depășit vârsta de școlarizare și nu și-au finalizat studiile, fiind o altă instituție juridică.', 'mediu', 'recall'),
('Din câți elevi pot fi alcătuite, ca regulă, formațiunile de studiu organizate cu persoanele private de libertate?', 'Din 8-12 elevi', 'Din 12-24 de elevi', 'Din 4-6 elevi', 'Din 16-30 de elevi', 'A', 'Legea învățământului preuniversitar nr. 198/2023 — Titlul I, cap. IV, art. 56', 'Legislație', 'Art. 56 alin. (1) prevede formațiuni de 8-12 elevi. Alin. (2) permite, în situații temeinic justificate și cu aprobarea DJIP/DMBIP, constituirea de grupe de 4-6 elevi sau majorarea efectivului peste maximul stabilit, în funcție de posibilitățile logistice ale locului de detenție, dar nu mai mult de 20 de elevi. Varianta c) descrie excepția, nu regula.', 'avansat', 'clasificare');


-- ---------- Verificare ----------
-- Trebuie să vezi 121 de întrebări, distribuite pe categorii.
SELECT category,
       COUNT(*)                                        AS intrebari,
       COUNT(*) FILTER (WHERE explanation IS NOT NULL)  AS cu_explicatie
FROM questions
GROUP BY category
ORDER BY intrebari DESC;
